(async () => {
  const w_slots = {
  "list": [
    1,
    2,
    3,
    4
  ],
  "op": "reduce",
  "initial": 0,
  "predicate": null
};
  const w_answer = await (async () => {
const slots = w_slots;
if (slots.op === "count") { return String(slots.list.length); }
if (slots.op === "sum") { return String(slots.list.reduce((sum, value) => sum + value, 0)); }
if (slots.op === "min") { return String(Math.min(...slots.list)); }
if (slots.op === "max") { return String(Math.max(...slots.list)); }
if (slots.op === "average") { return String(slots.list.reduce((sum, value) => sum + value, 0) / slots.list.length); }
if (slots.op === "median") {
  const ordered = [...slots.list].sort((left, right) => left - right);
  if (ordered.length % 2 !== 0) { throw new Error("the list has an even number of elements"); }
  return String(ordered[ordered.length / 2]);
}
